#include <iostream>
#include <set>
int main() {
    constexpr unsigned elements = 8, element_bytes = 4, line_bytes = 16;
    for (unsigned stride : {1u,4u}) {
        std::set<unsigned> blocks;
        for (unsigned i=0; i<elements; ++i)
            blocks.insert((i*stride*element_bytes)/line_bytes);
        std::cout << "stride=" << stride << " lines=" << blocks.size()
                  << " useful=" << elements*element_bytes
                  << " fetched=" << blocks.size()*line_bytes << '\n';
    }
}

#include <array>
#include <iostream>
int main() {
    std::array<int,12> values{};
    for (int i=0; i<12; ++i) values[i] = i;
    int rows = 0, columns = 0;
    for (int row=0; row<3; ++row)
        for (int col=0; col<4; ++col) rows += values[row*4+col];
    for (int col=0; col<4; ++col)
        for (int row=0; row<3; ++row) columns += values[row*4+col];
    std::cout << "rows=" << rows << " columns=" << columns << '\n';
    std::cout << "same=" << std::boolalpha << (rows == columns) << '\n';
}
